declare global {
  namespace Express { interface User { id: string; roles: string[]; tenant: string } }
}
app.use((req, _res, next) => {                          // verified once, at the boundary
  req.user = authenticate(req.headers.authorization);
  next();
});
app.get("/reports", (req, res) => {
  const user = req.user;                                // User | undefined
  if (!user) return res.sendStatus(401);
  res.json({ viewer: user.id, roles: user.roles });
});
